content.title:
$tmp = Join-Path $env:TEMP ('research-spine-flow-test-' + [guid]::NewGuid().ToString('N'));
New-Item -ItemType Directory -Path $tmp | Out-Null;
try {
  $env:RESEARCH_VAULT_ROOT = $tmp;
  node run.mjs pull research-spine-flow --documents daily-monitoring,daily-briefing | Out-Host;
  $matches = Get-ChildItem -Path $tmp -Recurse -Filter '*.md' | Select-String -Pattern 'Canonical Signal Intelligence|Deeper Dive Queue';
  $matches | ForEach-Object { "{0}:{1}:{2}" -f $_.Path, $_.LineNumber, $_.Line.Trim() };
} finally {
  Remove-Item Env:RESEARCH_VAULT_ROOT -ErrorAction SilentlyContinue;
  $resolvedTmp = (Resolve-Path -LiteralPath $tmp).Path;
  $tempRoot = (Resolve-Path -LiteralPath $env:TEMP).Path;
  if ($resolvedTmp.StartsWith($tempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
    Remove-Item -LiteralPath $resolvedTmp -Recurse -Force;
  }
}

